export function searchCompanies(query: string, limit: number = 8): StockItem[] {
  const cleanQuery = query.toLowerCase().trim();
  if (cleanQuery.length < 3) return [];
  
  return INDIAN_STOCKS.filter(
    stock => 
      stock.symbol.toLowerCase().includes(cleanQuery) || 
      stock.name.toLowerCase().includes(cleanQuery)
  ).slice(0, limit);
}

export function searchMutualFunds(query: string, limit: number = 8): MutualFundItem[] {
  const cleanQuery = query.toLowerCase().trim();
  if (cleanQuery.length < 3) return [];
  
  return POPULAR_MUTUAL_FUNDS.filter(
    fund => 
      fund.symbol.toLowerCase().includes(cleanQuery) || 
      fund.name.toLowerCase().includes(cleanQuery) ||
      fund.amc.toLowerCase().includes(cleanQuery)
  ).slice(0, limit);
}
